package com.externalvisuals.modules; import com.externalvisuals.module.Module; import com.externalvisuals.setting.*; public class KillEffects extends Module {public final ModeSetting effect=addSetting(new ModeSetting("Effect","LIGHTNING","LIGHTNING","EXPLOSION","HEART")); public final SliderSetting count=addSetting(new SliderSetting("Count",12,2,30,1)); public KillEffects(){super("Kill Effects");} public void play(net.minecraft.entity.Entity e){if(mc.world==null)return; for(int i=0;i<count.getValue().intValue();i++)mc.particleManager.addParticle(effect.getValue().equals("HEART")?net.minecraft.particle.ParticleTypes.HEART:net.minecraft.particle.ParticleTypes.EXPLOSION,e.getX(),e.getY()+e.getHeight()*.5,e.getZ(),(mc.world.random.nextDouble()-.5)*.15,.05,(mc.world.random.nextDouble()-.5)*.15);}}
